public sealed partial class DemoWorld
{
 public SpacePosition SolarOrigin;
 public string SolarCelestial="",SolarGridKey="",PendingGate="";
 public WarpTransit? Transit;
 public List<SpaceBookmark> Bookmarks=[];
 public List<string> Waypoints=[];
 public Dictionary<string,SolarGridMemory> SolarGrids=[];
 public bool Autopilot;public float Throttle=1,OrbitRange=1000,KeepRange=1000;public int DefaultWarpRange;
 public string DroneGridIdentity=>IsSolarGrid?SolarGridKey:Grid;
 public bool InWarp=>Transit!=null&&Transit.Phase!="Aligning";
 public SpacePosition SystemPosition=>InWarp?Transit!.From+(Transit.To-Transit.From).Unit*Transit.Curve.Sample(Transit.Elapsed).Distance:SolarOrigin+SpacePosition.From(Player.Position);
 public IEnumerable<Celestial> Celestials=>SolarCatalog.ForSystem(SystemId).Where(c=>c.Id!="umbra:signal"||SignalResolved);
 public bool IsSolarGrid=>SolarCelestial.Length>0||Grid=="deep_space";
 public void ResetSolar(){SolarOrigin=SolarCatalog.Resolve(SystemId,"station")!.WarpPosition;SolarCelestial=SystemId+":station";SolarGridKey=SolarCatalog.GridKey(SystemId,SolarOrigin);Transit=null;PendingGate="";Bookmarks.Clear();Waypoints.Clear();SolarGrids.Clear();Autopilot=false;Throttle=1;OrbitRange=KeepRange=1000;DefaultWarpRange=0;}
 static List<SpaceTarget> CopyTargets(IEnumerable<SpaceTarget> list)=>JsonSerializer.Deserialize<List<SpaceTarget>>(JsonSerializer.Serialize(list,WeaponCatalog.JsonOptions),WeaponCatalog.JsonOptions)??[];
 public void RememberSolarGrid(){if(!IsSolarGrid||InWarp||Docked)return;SolarGrids[SolarGridKey]=new(SolarOrigin,CopyTargets(Targets.Where(t=>!t.Friendly&&t.DroneId.Length==0)));}
 Celestial? PrepareSolarGrid(string id){var c=SolarCatalog.Resolve(SystemId,id);RememberSolarGrid();Transit=null;if(c==null){SolarCelestial="";return null;}SolarCelestial=c.Id;SolarOrigin=c.WarpPosition;SolarGridKey=SolarCatalog.GridKey(SystemId,SolarOrigin);return c;}
 void PopulateCelestialGrid(Celestial c){if(c.Kind==CelestialKind.Stargate)Targets.Add(new(){Id=c.Id,Name=c.Name,Kind=TargetKind.Stargate,Position=Vector3.Zero,Signature=3000});else if(c.Kind==CelestialKind.Wormhole)Targets.Add(new(){Id=c.Id,Name=c.Name,Kind=TargetKind.Wormhole,Signature=3000});else if(c.Kind==CelestialKind.Anomaly)Targets.Add(new(){Id=c.Id,Name=c.Name,Kind=TargetKind.Container,SiteKind="Relic",Position=new(1400,0,0),Contents=new(){{"salvage",30},{"ut_coolant",20}}});else if(c.Kind is CelestialKind.IceField or CelestialKind.GasCloud)Targets.Add(new(){Id="rock",Name=c.Kind==CelestialKind.IceField?"Glacial fragment":"Harvestable vapor cloud",Kind=TargetKind.Asteroid,Resource=c.Kind==CelestialKind.IceField?"ice":"gas",Ore=400,Position=new(1500,0,0),Signature=400});else Targets.Add(new(){Id=c.Id,Name=c.Name+" Orbital Point",Kind=TargetKind.Celestial,Signature=100});}
 void RestoreSolarGrid(Celestial? c){if(c==null)return;if(SolarGrids.TryGetValue(SolarGridKey,out var memory)){Targets.RemoveAll(t=>!t.Friendly&&t.DroneId.Length==0);var shift=(memory.Origin-SolarOrigin).Local;foreach(var t in CopyTargets(memory.Targets)){t.Position+=shift;Targets.Add(t);}}else if(ImportedWorld43){foreach(var belt in Celestials.Where(b=>b.Kind==CelestialKind.AsteroidBelt&&SolarCatalog.GridKey(SystemId,b.Position)==SolarGridKey))PopulateOriginalBelt43(belt);}else if(c.Kind==CelestialKind.AsteroidBelt){for(int i=0;i<13;i++){double a=i*.57;Targets.Add(new(){Id="rock:"+i,Name=i%4==0?"Deep alloy asteroid":"Vesperite asteroid "+(i+2),Kind=TargetKind.Asteroid,Resource=i%4==0?"deepore":"ore",Ore=100+i*17,Position=new((float)Math.Cos(a)*(5000+i*200),i%3*300,(float)Math.Sin(a)*(5000+i*300)),Signature=200});}}}
 public string AddBookmark(string name=""){var id="bookmark:"+Guid.NewGuid().ToString("N");Bookmarks.Add(new(id,SystemId,name.Length>0?name:Current.Name+" - Saved location "+(Bookmarks.Count+1),SystemPosition));Say("Location saved.");return id;}
 public bool ResolveWarpTarget(string id,out SpacePosition target,out string destination){if(MissionWarpTarget38(id,out target)){destination=id;return true;}var c=SolarCatalog.Resolve(SystemId,id);if(c!=null&&Celestials.Any(x=>x.Id==c.Id)){target=c.Anchor;destination=c.Id;return true;}var signature=UtilitySites.FirstOrDefault(s=>s.Id==id&&s.System==SystemId&&ProbeWarpable(s));if(signature!=null){var contact=Targets.FirstOrDefault(t=>t.Id==signature.TargetId&&t.Alive);if(signature.TargetId.Length>0&&!ProbeContactAlive(signature)){target=default;destination="";return false;}target=contact!=null?SolarOrigin+SpacePosition.From(contact.Position):new SpacePosition(signature.X*SolarCatalog.AU,signature.Y*SolarCatalog.AU,signature.Z*SolarCatalog.AU);destination=id;return true;}var b=Bookmarks.FirstOrDefault(b=>b.Id==id&&b.System==SystemId);if(b!=null){target=b.Position;destination=b.Id;return true;}var local=Targets.FirstOrDefault(t=>t.Id==id&&t.Alive);if(local!=null&&(local.Friendly||local.Kind is TargetKind.Station or TargetKind.Stargate or TargetKind.Wormhole or TargetKind.Celestial||(local.Kind is TargetKind.Wreck or TargetKind.Container)&&local.OwnerId=="player")){target=SolarOrigin+SpacePosition.From(local.Position);destination=id;return true;}target=default;destination="";return false;}
 public double WarpDistance(string id)=>ResolveWarpTarget(id,out var p,out _)?(p-SystemPosition).Length:0;
 public bool BeginWarp(string id,int range=0,string arrival="")
 {
  if(!TravelInterlockQ()||RobbingQ)return false;if(InAbyssF)return false;
  if(Docked||Screen!=ViewMode.Space){Say("Undock before warping.");return false;}if(Transit!=null){Say("Warp is already in progress.");return false;}if(IndustrialCore||Player.MobilitySpooling||Player.DriveLockout>0||WarpBlocked("player")){Say("Warp blocked by drive interlock or interdiction.");return false;}
  if(!ResolveWarpTarget(id,out var target,out var destination)){Say("No accessible warp solution for that object.");return false;}if(range<0||range>100000){Say("Choose a warp range from 0 to 100 km.");return false;}var from=SystemPosition;double distance=(target-from).Length;if(distance<SolarCatalog.MinimumWarp){Say("Warp target is closer than 150 km.");return false;}
  if(Player.Drones.Any(d=>d.Location=="Space"))Say("Warning: deployed drones remain behind when entering warp. Recall them before travel.");
  // Exit point is fixed now; it does not follow a moving target.
  var direction=(target-from).Unit;var to=target-direction*range+new SpacePosition(0,1200,0);double desired=(to-from).Length;float cost=WarpEnergyCost((float)(desired/SolarCatalog.AU));bool partial=cost>Player.Cap;double maxDistance=partial?desired*Player.Cap/Math.Max(.0001,cost):desired;if(maxDistance<SolarCatalog.MinimumWarp){Say("Insufficient capacitor to establish a 150 km warp.");return false;}if(partial)to=from+(to-from).Unit*maxDistance;
  PendingGate="";Transit=new(){Target=destination,From=from,To=to,Range=range,Partial=partial,Arrival=partial?"":arrival};Throttle=1;DockPending=false;Player.Order="warpAlign";Player.OrderTarget="";Player.ManualPoint=Player.Position+(to-from).Unit.Local*1000000;Say("Establishing warp vector / "+SolarCatalog.Distance(maxDistance)+(partial?" / capacitor-limited":""));return true;
 }
 public void CancelWarp(){if(Transit?.Phase=="Aligning"){Transit=null;StopShip();Say("Warp command cancelled.");}else if(InWarp)Say("Warp cannot be cancelled in transit.");}
 public void StopShip(){if(InWarp){Say("Ship is in warp.");return;}Transit=null;PendingGate="";Autopilot=false;Player.Order="stop";Player.OrderTarget="";DockPending=false;}
 public void AlignTo(string id){if(InWarp)return;if(ResolveWarpTarget(id,out var p,out _)){Transit=null;PendingGate="";Player.ManualPoint=Player.Position+(p-SystemPosition).Unit.Local*1000000;Player.Order="align";Player.OrderTarget="";Throttle=1;Say("Aligning to destination.");}}
 public void SetNavigationRange(string order,float meters){if(meters<0||meters>100000)return;if(order=="orbit")OrbitRange=meters;else KeepRange=meters;SetOrder(order);}
 bool UpdateSolarTravel(float dt)
 {
  var trip=Transit;if(trip==null)return false;
  if(trip.Phase=="Aligning"){
   if(IndustrialCore||Player.MobilitySpooling||Player.DriveLockout>0||WarpBlocked("player")){Transit=null;Player.Order="stop";Say("Warp interrupted during alignment.");return false;}trip.AlignElapsed+=dt;var direction=(trip.To-SystemPosition).Unit.Local;float max=Player.Speed*EwarFor("player").Speed;float speed=Player.Velocity.Length();bool aligned=speed>=max*.7499f&&speed>0&&Vector3.Dot(Player.Velocity/speed,direction)>.998f;
   if(!aligned&&trip.AlignElapsed<180)return false;float cost=WarpEnergyCost((float)((trip.To-SystemPosition).Length/SolarCatalog.AU));if(!PayWarpEnergy((float)((trip.To-SystemPosition).Length/SolarCatalog.AU))){Transit=null;Player.Order="stop";return false;}
   RememberSolarGrid();trip.From=SystemPosition;trip.Curve=WarpCurve.Calculate((trip.To-trip.From).Length,Math.Max(.1,WarpRate),Math.Max(1,max),Player.HullFactor("hull","warpAcceleration"));trip.Phase="Accelerating";LockedId=SelectedId=PendingLockId="";ClearEnhancedLocks();Player.Order="warp";foreach(var w in Player.Weapons)w.Stop();Say("Warp drive active.");
  }
  trip.Elapsed=Math.Min(trip.Curve.Total,trip.Elapsed+dt);trip.Phase=trip.Curve.Sample(trip.Elapsed).Phase;
  if(trip.Elapsed<trip.Curve.Total)return true;
  string arrival=trip.Arrival,target=trip.Target;SpacePosition to=trip.To;bool partial=trip.Partial;Transit=null;
  if(!partial&&target.StartsWith("mission:")&&EnterMission38(target)){SolarOrigin=to;}
  else if(!partial&&UtilitySites.FirstOrDefault(s=>s.Id==target&&s.System==SystemId&&ProbeWarpable(s)) is {} site){if(site.Id=="umbra:signal")EnterGrid("signal",false);else if(site.TargetId.Length>0)EnterDeepSpace(to);else EnterResolvedUtilitySite(site,to);}
  else if(!partial&&SolarCatalog.Resolve(SystemId,target) is {} c){EnterGrid(c.Id,false);Player.Position=(to-SolarOrigin).Local;}
  else{EnterDeepSpace(to);}
  Player.Velocity=(trip.To-trip.From).Unit.Local*(float)trip.Curve.ExitSpeed;Player.Facing=(trip.To-trip.From).Unit.Local;Player.Order="stop";Say("Warp complete / "+SolarCatalog.Distance(trip.Curve.Distance)+" / "+trip.Curve.Total.ToString("0.0")+" s.");
  if(arrival=="dock")Dock();else if(arrival=="jump"&&SolarCatalog.Resolve(SystemId,target) is {} gate)UseSolarGate(gate.Id);return true;
 }
 public void EnterDeepSpace(SpacePosition position){var nearby=Celestials.FirstOrDefault(c=>SolarCatalog.GridKey(SystemId,c.WarpPosition)==SolarCatalog.GridKey(SystemId,position));if(nearby!=null){EnterGrid(nearby.Id,false);Player.Position=(position-SolarOrigin).Local;return;}RememberSolarGrid();EnterGrid("deep_space",false);Targets.Clear();SolarCelestial="";SolarOrigin=SolarCatalog.GridCenter(position);SolarGridKey=SolarCatalog.GridKey(SystemId,position);Player.Position=(position-SolarOrigin).Local;if(SolarGrids.TryGetValue(SolarGridKey,out var memory)){foreach(var t in CopyTargets(memory.Targets)){t.Position+=(memory.Origin-SolarOrigin).Local;Targets.Add(t);}}}
 void UpdateSolarBoundary(){if(InAbyssF)return;if(!IsSolarGrid||InWarp||Transit!=null)return;var global=SystemPosition;string key=SolarCatalog.GridKey(SystemId,global);if(key==SolarGridKey)return;var nearby=Celestials.FirstOrDefault(c=>SolarCatalog.GridKey(SystemId,c.WarpPosition)==key);if(nearby!=null){var velocity=Player.Velocity;var manual=SolarOrigin+SpacePosition.From(Player.ManualPoint);string order=Player.Order;EnterGrid(nearby.Id,false);Player.Position=(global-SolarOrigin).Local;Player.ManualPoint=(manual-SolarOrigin).Local;Player.Velocity=velocity;Player.Order=order;return;}RememberSolarGrid();var old=SolarOrigin;SolarOrigin=SolarCatalog.GridCenter(global);SolarGridKey=key;SolarCelestial="";Grid="deep_space";Player.Position=(global-SolarOrigin).Local;Player.ManualPoint+=(old-SolarOrigin).Local;Targets.Clear();MissilesInFlight.Clear();LockedId=PendingLockId="";ClearEnhancedLocks();if(SolarGrids.TryGetValue(key,out var memory)){foreach(var t in CopyTargets(memory.Targets)){t.Position+=(memory.Origin-SolarOrigin).Local;Targets.Add(t);}}Say("Local grid boundary crossed.");}
 public bool UseSolarGate(string id){if(!TravelInterlockQ(true)||RobbingQ)return false;if(InAbyssF)return false;if(InWarp||Transit!=null||Docked||!CanUseGate("player"))return false;var gate=SolarCatalog.Resolve(SystemId,id);if(gate==null||gate.Kind is not (CelestialKind.Stargate or CelestialKind.Wormhole))return false;if((gate.Anchor-SystemPosition).Length>2500){if((gate.Anchor-SystemPosition).Length>=SolarCatalog.MinimumWarp)return BeginWarp(gate.Id,0,"jump");SelectedId=gate.Id;SetOrder("approach");PendingGate=gate.Id;return true;}string regionError=HubGateErrorH(gate.Destination);if(regionError!=""){Say(regionError);return false;}PendingGate="";RememberSolarGrid();RecoverProbesForTransit();string old=SystemId;LeaveSupportGrid(true);SystemId=gate.Destination;HubGateEnteredH(old);string reverse=ImportedWorld43?"stargate:"+Spatial43.Get(old).ById[gate.Id].DestinationGateId:gate.Kind==CelestialKind.Stargate?SystemId+":gate:"+old:SystemId+":wormhole";EnterGrid(reverse,false);Player.Position=new(0,1200,0);Player.Velocity=Vector3.Zero;Player.Order="stop";AdvanceHours(.5/3600);Say("Gate transit complete / "+Current.Name);return true;}
 public void SetDestination(string system,bool append=false){if(!(ImportedWorld43?Spatial43.IsSystem(system):Systems.Any(s=>s.Id==system)))return;if(!append)Waypoints.Clear();if(system!=SystemId)Waypoints.Add(system);Say("Route updated.");}
 public List<string> Route(){if(ImportedWorld43){var imported=new List<string>();int start=int.Parse(SystemId[7..]);foreach(var goal in Waypoints){if(!Spatial43.IsSystem(goal))break;var path=Galaxy42.Route(start,int.Parse(goal[7..]),GalaxyPlan?.Mode??GalaxyRouteMode42.Shortest,GalaxyPlan?.Avoid);if(!path.Found)break;imported.AddRange(path.Systems.Skip(1).Select(x=>"system:"+x));start=int.Parse(goal[7..]);}return imported;}var route=new List<string>();string from=SystemId;foreach(var goal in Waypoints){var queue=new Queue<string>();queue.Enqueue(from);var previous=new Dictionary<string,string>{{from,""}};while(queue.Count>0&&!previous.ContainsKey(goal)){var current=queue.Dequeue();foreach(string next in Systems.First(s=>s.Id==current).Links)if(previous.TryAdd(next,current))queue.Enqueue(next);}if(!previous.ContainsKey(goal))break;var part=new List<string>();for(string node=goal;node!=from;node=previous[node])part.Add(node);part.Reverse();route.AddRange(part);from=goal;}return route;}
 void UpdatePendingGate(){if(PendingGate.Length>0&&Transit==null&&WarpDistance(PendingGate)<=2500)UseSolarGate(PendingGate);}
 void UpdateAutopilot(){if(!Autopilot||Docked||Transit!=null)return;while(Waypoints.FirstOrDefault()==SystemId)Waypoints.RemoveAt(0);var route=Route();if(route.Count==0){Autopilot=false;return;}string gateId=ImportedWorld43?Spatial43.GateTo(SystemId,route[0]):SystemId+":gate:"+route[0];if(gateId.Length==0){Autopilot=false;return;}if(WarpDistance(gateId)>=SolarCatalog.MinimumWarp)BeginWarp(gateId,10000);else if(WarpDistance(gateId)>2500){SelectedId=gateId;var gate=Targets.FirstOrDefault(t=>t.Id==gateId);if(gate!=null){Player.Order="approach";Player.OrderTarget=gateId;Throttle=1;}}else UseSolarGate(gateId);}
 public void UpdateSolarPreview(float seconds){for(int i=0;i<(int)(seconds/.05f);i++)Update(.05f);}
 public SolarSave CaptureSolar(){RememberSolarGrid();return new(){Origin=SolarOrigin,Celestial=SolarCelestial,GridKey=SolarGridKey,PendingGate=PendingGate,Transit=Transit,Bookmarks=Bookmarks,Waypoints=Waypoints,Grids=SolarGrids,Autopilot=Autopilot,Throttle=Throttle,Orbit=OrbitRange,Keep=KeepRange,WarpRange=DefaultWarpRange};}
 public void RestoreSolar(SolarSave? state){if(state==null){SolarOrigin=SolarCatalog.Resolve(SystemId,Grid)?.WarpPosition??default;SolarCelestial=SolarCatalog.Resolve(SystemId,Grid)?.Id??"";SolarGridKey=SolarCatalog.GridKey(SystemId,SystemPosition);Transit=null;return;}SolarOrigin=state.Origin;SolarCelestial=state.Celestial;SolarGridKey=state.GridKey;PendingGate=state.PendingGate;Transit=state.Transit;Bookmarks=state.Bookmarks;Waypoints=state.Waypoints;SolarGrids=state.Grids;Autopilot=state.Autopilot;Throttle=state.Throttle;OrbitRange=state.Orbit;KeepRange=state.Keep;DefaultWarpRange=state.WarpRange;if(SolarGrids.TryGetValue(SolarGridKey,out var memory)){Targets=CopyTargets(memory.Targets);foreach(var t in Targets)t.Position+=(memory.Origin-SolarOrigin).Local;RestoreDroneGrid();RestoreWingmates();}if(Transit?.Phase=="Aligning"){Player.Order="warpAlign";Player.ManualPoint=Player.Position+(Transit.To-SystemPosition).Unit.Local*1000000;}else if(InWarp)Player.Order="warp";}
}
